-- HySmart Station v0.3.0 core schema. Review on staging before production.
create extension if not exists pgcrypto;
create table if not exists public.companies(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name)) between 2 and 160),created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.company_members(company_id uuid not null references public.companies(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('COMPANY_OWNER','COMPANY_ADMIN')),status text not null default 'active' check(status in ('active','removed','suspended')),created_at timestamptz not null default now(),primary key(company_id,user_id));
create table if not exists public.stations(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null check(length(trim(name)) between 2 and 120),address text not null, status text not null default 'active' check(status in ('active','inactive')),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.station_members(station_id uuid not null references public.stations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('STATION_MANAGER','ATTENDANT')),status text not null default 'active' check(status in ('active','removed','suspended')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(station_id,user_id));
create table if not exists public.audit_events(id uuid primary key default gen_random_uuid(),company_id uuid references public.companies(id) on delete set null,station_id uuid references public.stations(id) on delete set null,actor_user_id uuid references auth.users(id) on delete set null,action text not null,entity_type text not null,entity_id text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists stations_company_idx on public.stations(company_id);create index if not exists station_members_user_idx on public.station_members(user_id,status);create index if not exists audit_events_station_created_idx on public.audit_events(station_id,created_at desc);
-- Enable RLS. API uses server-side service key only after verifying the caller's JWT.
alter table public.companies enable row level security;alter table public.company_members enable row level security;alter table public.stations enable row level security;alter table public.station_members enable row level security;alter table public.audit_events enable row level security;
